{
  "actions": [
    {
      "action": "Replace “complete” with component-level evidence",
      "mechanism": "Separate presence from condition so counting never implies inspection, and previous good condition cannot silently carry forward.",
      "implementation": "Use a paper sheet listing ten IDs, presence, condition category or unknown, inspector initials, and time. Start each transaction with condition unknown.",
      "check": "Record a counted-only return: all ten IDs show present, all conditions remain unknown, and no verified-good summary appears.",
      "risk": "Pre-filled condition values could conceal skipped inspections."
    },
    {
      "action": "Require an explicit shift-transfer receipt",
      "mechanism": "Keep inspection authorship unchanged while transferring responsibility for unfinished work to a named receiving staff member.",
      "implementation": "Attach the evidence sheet to the kit record. Outgoing staff list unresolved IDs; incoming staff initial acceptance and the next review time.",
      "check": "After a shift change, ask incoming staff to identify outstanding checks, their owner, and who recorded each existing inspection.",
      "risk": "An unsigned transfer needs a named duty-lead fallback."
    },
    {
      "action": "Turn missing components into assigned recovery tasks",
      "mechanism": "A missing ID creates an owned task rather than disappearing inside a general incomplete status.",
      "implementation": "For each missing ID, record an owner, next action, and due time; begin with a storage-area search, then borrower contact if unresolved.",
      "check": "Simulate one missing component. Verify its task survives shift transfer and closes only after recovery evidence or an authorized disposition.",
      "risk": "Duplicate tasks may arise unless linked to the transaction."
    },
    {
      "action": "Timebox handoffs without converting uncertainty into approval",
      "mechanism": "Separate custody transfer from readiness to lend; unfinished inspection can remain pending without extending the handoff.",
      "implementation": "Use a shared clock: stop inspection at two minutes, reserve one minute for ownership transfer, and keep unresolved kits off the lending shelf.",
      "check": "Time a counted-only return through transfer: finish within three minutes, preserve unknown conditions, and assign remaining inspection before release.",
      "risk": "Pending kits need scheduled review to avoid indefinite delays."
    }
  ],
  "abstention_reason": ""
}
